import { z } from 'zod';

export const AgentResponseSchema = z.object({
  thought: z.string().describe('Step-by-step reasoning'),
  action: z.enum(['search', 'execute', 'finish']),
  parameters: z.record(z.any()),
  finalAnswer: z.string().optional(),
});

export type AgentResponse = z.infer<typeof AgentResponseSchema>;

from pydantic import BaseModel, Field
from typing import Optional

class WeatherInput(BaseModel):
    city: str = Field(description='City name, e.g. Baku, Paris')
    units: Optional[str] = Field(default='celsius', description='Temperature units')

def get_weather(input_data: WeatherInput) -> dict:
    '''Retrieves real-time weather observations for a city.'''
    return {'city': input_data.city, 'temperature': 21.5, 'units': input_data.units}
